  if (reentered) return;
  reentered = true;
  const outcome = outcomeOf(() => reenter.call(host));
  record(`reentry ${outcome.thrown === undefined ? "accepted" : describeError(outcome.thrown)}`);
  if (outcome.thrown !== undefined && reenter.swallow !== true) throw outcome.thrown;
};

